def convert_list_dictionary(*lists):
    if not lists or len(lists) < 3:
        return []
    result = []
    for i in range(len(lists[0])):
        nested_dict = {}
        for j in range(len(lists)):
            if j == 0:
                key1 = lists[j][i]
                nested_dict[key1] = {}
            elif j == 1:
                key2 = lists[j][i]
                nested_dict[key1][key2] = lists[j+1][i]
        result.append(nested_dict)
    return result
